def destroy
  if ::OnlineStatusTracker.get_presence(@contact.account.id, 'Contact', @contact.id)
    return render_error(..., :unprocessable_entity)
  end
  @contact.destroy!
  head :ok
end

def update_last_seen_on_conversation(last_seen_at, update_assignee)
  updates = { agent_last_seen_at: last_seen_at }
  updates[:assignee_last_seen_at] = last_seen_at if update_assignee.present?
  @conversation.update_columns(updates)
end

ActiveRecord::Base.transaction do
  channel = create_channel
  @inbox = Current.account.inboxes.build({ name: inbox_name(channel), channel: channel }.merge(permitted_params.except(:channel)))
  @inbox.save!
end

def update
  if password_params[:password].present?
    render_could_not_create_error('Invalid current password') and return unless @user.valid_password?(password_params[:current_password])
    @user.update!(password_params.except(:current_password))
  end
  @user.assign_attributes(profile_params)
  @user.custom_attributes.merge!(custom_attributes_params)
  @user.save!
end
